## My answer to the prompt

The original server reads **one pair of native 32-bit `int`s** from each datagram, while the example describes **18 pairs of 16-bit values**. I would define an explicit wire format so both sides agree: **18 `(event_index, event_value)` pairs, each field a signed 16-bit value in big-endian byte order**. That makes the packet exactly 72 bytes and avoids relying on either machine’s native byte order or struct layout.

On the C side, receive a complete packet, decode each pair, and process it:

```c
#define EVENT_COUNT (sizeof(REGISTERED_EVENTS) / sizeof(REGISTERED_EVENTS[0]))
#define PACKET_SIZE (EVENT_COUNT * 4)

static uint16_t read_be16(const unsigned char *p) {
    return ((uint16_t)p[0] << 8) | p[1];
}

/* In udp_server(), use an unsigned-char buffer of at least PACKET_SIZE bytes. */
unsigned char buffer[PACKET_SIZE];

ssize_t n = recvfrom(sockfd, buffer, sizeof buffer, MSG_TRUNC,
                     (struct sockaddr *)&cli_addr, &cli_len);
if (n != PACKET_SIZE) {
    fprintf(stderr, "Expected %d-byte packet, received %zd bytes\n",
            PACKET_SIZE, n);
    continue;
}

for (size_t i = 0; i < EVENT_COUNT; ++i) {
    const unsigned char *p = buffer + i * 4;
    uint16_t index = read_be16(p);
    uint16_t raw_value = read_be16(p + 2);

    /* Decode the two's-complement 16-bit value without relying on host byte order. */
    int32_t value = raw_value <= INT16_MAX
        ? raw_value
        : (int32_t)raw_value - 65536;

    if (index < EVENT_COUNT) {
        libevdev_uinput_write_event(controller,
            REGISTERED_EVENTS[index].type,
            REGISTERED_EVENTS[index].code,
            value);
    }
}
libevdev_uinput_write_event(controller, EV_SYN, SYN_REPORT, 0);
```

On the Zig side, serialize each index and value into those same four bytes. This avoids depending on Zig struct padding or native endianness:

```zig
const EVENT_COUNT = 18;

fn writeBe16(bytes: []u8, value: u16) void {
    bytes[0] = @truncate(value >> 8);
    bytes[1] = @truncate(value);
}

fn sendControllerState(
    sock: posix.fd_t,
    addr: *const net.Address,
    state: []const i16,
) !void {
    var packet: [EVENT_COUNT * 4]u8 = undefined;

    for (0..EVENT_COUNT) |i| {
        const index: u16 = @intCast(i);
        const value_bits: u16 = @bitCast(state[i]);
        writeBe16(packet[i * 4 ..][0..2], index);
        writeBe16(packet[i * 4 + 2 ..][0..2], value_bits);
    }

    const sent = try posix.sendto(
        sock,
        &packet,
        0,
        &addr.any,
        addr.getOsSockLen(),
    );
    if (sent != packet.len) return error.IncompleteDatagramSend;
}
```

